"""Tests for cart_cli.py."""

import io
import unittest
from contextlib import redirect_stderr, redirect_stdout

from cart_cli import main, parse_discount, parse_item


def run_cli(*argv):
    """Run the CLI with captured streams, normalising SystemExit to a code."""
    stdout, stderr = io.StringIO(), io.StringIO()
    with redirect_stdout(stdout), redirect_stderr(stderr):
        try:
            code = main(list(argv))
        except SystemExit as exc:
            code = 0 if exc.code is None else exc.code
    return code, stdout.getvalue(), stderr.getvalue()


class ParseItemTests(unittest.TestCase):
    def test_parses_quantity_and_unit_cents(self):
        self.assertEqual(parse_item("3x250"), (3, 250))

    def test_tolerates_spaces_and_capital_x(self):
        self.assertEqual(parse_item(" 2 X 499 "), (2, 499))

    def test_allows_free_item(self):
        self.assertEqual(parse_item("1x0"), (1, 0))

    def test_rejects_malformed_items(self):
        for text in ["3", "3*250", "0x250", "2x-5", "2.5x250", "2x25.5", "x250", "2x", ""]:
            with self.subTest(text=text):
                with self.assertRaises(Exception) as ctx:
                    parse_item(text)
                self.assertIsInstance(ctx.exception, SystemExit.__mro__[1])  # ArgumentTypeError


class ParseDiscountTests(unittest.TestCase):
    def test_accepts_boundaries(self):
        self.assertEqual(parse_discount("0"), 0)
        self.assertEqual(parse_discount("100"), 100)

    def test_accepts_whitespace(self):
        self.assertEqual(parse_discount(" 5 "), 5)

    def test_rejects_out_of_range_and_non_integers(self):
        for text in ["-1", "101", "5.5", "five", ""]:
            with self.subTest(text=text):
                with self.assertRaises(Exception):
                    parse_discount(text)


class MainTests(unittest.TestCase):
    def test_prints_formatted_total(self):
        code, stdout, stderr = run_cli("2x499", "1x52")
        self.assertEqual((code, stdout, stderr), (0, "Total: 10.50\n", ""))

    def test_applies_discount(self):
        code, stdout, _ = run_cli("2x499", "1x52", "--discount", "10")
        self.assertEqual((code, stdout), (0, "Total: 9.45\n"))

    def test_full_discount(self):
        code, stdout, _ = run_cli("3x333", "-d", "100")
        self.assertEqual((code, stdout), (0, "Total: 0.00\n"))

    def test_bad_item_exits_with_usage_error(self):
        code, stdout, stderr = run_cli("2*499")
        self.assertEqual(code, 2)
        self.assertEqual(stdout, "")
        self.assertIn("invalid item", stderr)

    def test_bad_discount_exits_with_usage_error(self):
        code, stdout, stderr = run_cli("1x100", "-d", "150")
        self.assertEqual(code, 2)
        self.assertEqual(stdout, "")
        self.assertIn("invalid discount", stderr)

    def test_requires_at_least_one_item(self):
        code, _, stderr = run_cli()
        self.assertEqual(code, 2)
        self.assertIn("required", stderr)


if __name__ == "__main__":
    unittest.main()
